`timescale 1ns/1ps
// chi_xilinx_netlist_GHPCLL_wrapper
// Top-level wrapper for chi_GHPCLL__d1 with on-chip LFSRs.
// Internalizes all ports to allow full post-implementation metrics.
// Fresh, state_in generated by LFSRs → only clk, rst, result as pins.

module chi_xilinx_netlist_GHPCLL_wrapper (
    input  wire clk,
    input  wire rst,
    output wire result    // prevents logic optimization
);
    wire [1599:0]  state_in_s0;
    wire [1599:0]  state_in_s1;
    wire [12799:0] Fresh;
    wire [1599:0]  out_s0;
    wire [1599:0]  out_s1;

    genvar i;
    generate
        // LFSR for state_in_s0
        for (i = 0; i < 1600; i = i + 1) begin : GEN_STATE_S0
            LFSR31 lfsr_s0 (.clk(clk), .rst(rst), .out(state_in_s0[i]));
        end
        // LFSR for state_in_s1
        for (i = 0; i < 1600; i = i + 1) begin : GEN_STATE_S1
            LFSR31 lfsr_s1 (.clk(clk), .rst(rst), .out(state_in_s1[i]));
        end
        // LFSR for Fresh (12800 bits for GHPCLL)
        for (i = 0; i < 12800; i = i + 1) begin : GEN_FRESH
            LFSR31 lfsr_f  (.clk(clk), .rst(rst), .out(Fresh[i]));
        end
    endgenerate

    // Chi GHPCLL block
    chi_GHPCLL__d1 chi_inst (
        .clk           (clk),
        .state_in1_s0  (state_in_s0),
        .state_in1_s1  (state_in_s1),
        .Fresh         (Fresh),
        .state_out1_s0 (out_s0),
        .state_out1_s1 (out_s1)
    );

    // Prevent optimization
    assign result = ^(out_s0 ^ out_s1);

endmodule
